begin;
create temporary table gldd_test_ids as select gen_random_uuid() as staff, (select user_id from gldd_private.app_owner limit 1) as owner, (select id from public.bjta_businesses where active limit 1) as business;
insert into auth.users(id,email) select staff,'gldd-rollback-'||staff||'@example.invalid' from gldd_test_ids;
insert into public.bjta_staff(business_id,user_id,display_name,roles,active) select business,staff,'Rollback Driver',array['driver'],true from gldd_test_ids;
select set_config('request.jwt.claim.sub',owner::text,true) from gldd_test_ids;
select public.gldd_set_staff_status(business,staff,true,false) from gldd_test_ids;
do $$begin if not exists(select 1 from public.gldd_staff_events e join gldd_test_ids t on t.staff=e.user_id where e.action='access_revoked' and e.actor_id=t.owner) then raise exception 'Missing revoke audit'; end if; end$$;
select set_config('request.jwt.claim.sub',staff::text,true) from gldd_test_ids;
do $$begin if (public.gldd_get_my_access()->'memberships')<>'[]'::jsonb then raise exception 'Revoked driver retains membership';end if;end$$;
set local role authenticated;
do $$begin if exists(select 1 from public.bjta_days) or exists(select 1 from public.bjta_deliveries) then raise exception 'Revoked driver can read delivery data';end if;end$$;
reset role;
do $$declare t record;begin select * into t from gldd_test_ids;begin perform public.gldd_set_staff_status(t.business,t.staff,false,true);raise exception 'Unauthorized restore allowed';exception when others then if sqlerrm not like '%Super Admin access required%' then raise;end if;end;end$$;
select set_config('request.jwt.claim.sub',owner::text,true) from gldd_test_ids;
select public.gldd_set_staff_status(business,staff,false,true) from gldd_test_ids;
do $$declare t record;begin select * into t from gldd_test_ids;begin perform public.gldd_set_staff_status(t.business,t.owner,true,false);raise exception 'Owner changed';exception when others then if sqlerrm not like '%protected%' then raise;end if;end;begin perform public.gldd_set_staff_status(t.business,t.staff,false,false);raise exception 'Stale state accepted';exception when others then if sqlerrm not like '%Access changed%' then raise;end if;end;end$$;
select set_config('request.jwt.claim.sub',staff::text,true) from gldd_test_ids;
do $$begin if jsonb_array_length(public.gldd_get_my_access()->'memberships')<>1 then raise exception 'Restore failed';end if;end$$;
set local role authenticated;
do $$begin if exists(select 1 from public.gldd_staff_events) then raise exception 'Driver sees staff audit';end if;end$$;
reset role;
select 'passed: revoke, restore, live membership, owner protection, stale-state guard, audit actor, driver audit privacy; all fixtures rolled back' as verification;
rollback;
